Here is a simple C++ program that finds the nth Fibonacci number using recursion:

```c++
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int Fib(int n) {
    if (n <= 1) return n;
    else return Fib(n-1) + Fib(n - 2);
}

int main() {
    int n;
    cin >> n;
    vector<int> fibonacci(n + 1);
    for (int i = 0; i <= n; i++) {
        fibonacci[i] = Fib(i);
    }
    cout << fibonacci[n] << endl;
    return 0;
}
```

